    ('Änderungszeit der Datei (kein Zeitstempel gefunden)', 'modification time of the file (no time stamp found)', 'เวลาแก้ไขไฟล์ (ไม่พบเวลาประทับ)'),
    ('{name}: ohne Zeitstempel, nach Änderungszeit eingereiht: {files}', '{name}: no time stamp, placed by modification time: {files}', '{name}: ไม่มีเวลาประทับ เรียงตามเวลาแก้ไข: {files}'),
    ('{file}: Start {time} ({source})', '{file}: start {time} ({source})', '{file}: เริ่ม {time} ({source})'),
    ('Analyse {path}: {files} Dateien gelesen', 'Analysis {path}: {files} files read', 'วิเคราะห์ {path}: อ่าน {files} ไฟล์'),
    ('Lese Dateien', 'Reading files', 'กำลังอ่านไฟล์'),
    ('Erzeuge Bilder', 'Creating images', 'กำลังสร้างภาพ'),
    ('Schreibe Ergebnisdatei', 'Writing result file', 'กำลังเขียนไฟล์ผลลัพธ์'),
    ('Auto: Abbrechen...', 'Auto: cancelling...', 'อัตโนมัติ: กำลังยกเลิก...'),
    ('{what} {done}/{total}: {name}', '{what} {done}/{total}: {name}', '{what} {done}/{total}: {name}'),
    ('Analysiere Quellordner', 'Analysing source folder', 'กำลังวิเคราะห์โฟลเดอร์ต้นทาง'),
    ('Verarbeite Daten', 'Processing data', 'กำลังประมวลผลข้อมูล'),
    ('Auto: {text}', 'Auto: {text}', 'อัตโนมัติ: {text}'),
    ('Abgebrochen - der Rest folgt im nächsten Zyklus.', 'Cancelled - the rest follows in the next cycle.', 'ยกเลิกแล้ว - ส่วนที่เหลือทำในรอบถัดไป'),
