    ('Limit_min: {value}', 'Limit_min: {value}', 'Limit_min: {value}'),
    ('Regression ({n}): {name}', 'Regression ({n}): {name}', 'การถดถอย ({n}): {name}'),
    ('x: Sekunden ab {start}', 'x: seconds from {start}', 'x: วินาทีนับจาก {start}'),
    ('Zielzeit: -', 'Target time: -', 'เวลาเป้าหมาย: -'),
