_TRANSLATIONS = {"English": {de: en for de, en, _ in _TABLE}, "Thai": {de: th for de, _, th in _TABLE}}
from .i18n_zh import ZH as _ZH  # noqa: E402  (Chinesisch: Deutsch -> Chinesisch)
_TRANSLATIONS["Chinese"] = dict(_ZH)
_FALLBACK = {"Chinese": "English"}           # fehlt eine Übersetzung: Englisch statt Deutsch


def set_language(language: str) -> None:
    global _current
    _current = language if language in LANGUAGES else DEFAULT


def language() -> str:
    return _current


class Translated(str):
    """Übersetzter Text, der Schlüssel und Werte behält: retranslate() zeigt ihn später in einer anderen Sprache.

    Verhält sich sonst wie ein normaler String (Vergleich, Verketten, JSON, Pickle)."""

    def __new__(cls, value: str, key: str, values: dict):
        obj = super().__new__(cls, value)
        obj.key, obj.values = key, values
        return obj

    def __reduce__(self):
        return (Translated, (str(self), self.key, self.values))


def t(text: str, /, **values) -> str:
    """Text in der eingestellten Sprache; Platzhalter {name} werden ersetzt."""
    table = _TRANSLATIONS.get(_current, {})
    result = table.get(text)
    if result is None:
        result = _TRANSLATIONS.get(_FALLBACK.get(_current, ""), {}).get(text, text)
    return Translated(result.format(**values) if values else result, text, values)


def retranslate(text):
    """Mit t() erzeugten Text in der jetzt eingestellten Sprache (auch eingesetzte Werte); anderes unverändert.

    Für Angaben, die beim Laden entstehen und später angezeigt werden (Erkennung einer Datei): Sonst bliebe nach
    einem Sprachwechsel z. B. Thai stehen, das die Schrift der anderen Sprachen nicht darstellen kann."""
    if not isinstance(text, Translated):
        return text
    values = {k: retranslate(v) for k, v in text.values.items()}
    try:
        return t(text.key, **values)
    except (KeyError, IndexError, ValueError):
        return text


def translate_to(language_name: str, text: str) -> str:
    """Übersetzung in eine bestimmte Sprache, unabhängig von der Einstellung (z. B. für die Hilfe)."""
    found = _TRANSLATIONS.get(language_name, {}).get(text)
    if found is None:
        found = _TRANSLATIONS.get(_FALLBACK.get(language_name, ""), {}).get(text, text)
    return found


def keys() -> list[str]:
    return [de for de, _, _ in _TABLE]
